/** Deterministic exact release selection; it is separate from every prop catalog. */
export const NPC_APPEARANCE_CATALOG: readonly GeneratedNpcAppearance[] =
  Object.freeze(Object.values(GENERATED_NPC_APPEARANCES));

/** Exact-only lookup. It never substitutes an appearance or rules identity. */
export function resolveNpcAppearance(
  assetRef: string,
  onDiagnostic?: (diagnostic: NpcAppearanceResolutionDiagnostic) => void
): GeneratedNpcAppearance | undefined {
  const appearance = Object.hasOwn(GENERATED_NPC_APPEARANCES, assetRef)
    ? GENERATED_NPC_APPEARANCES[assetRef]
    : undefined;
  if (!appearance) {
    onDiagnostic?.({ assetRef, reason: 'unsupported-exact-asset-ref' });
  }
  return appearance;
}
